SELECT p.gender, CAST(p.anchor_age AS INT) AS age, d.name AS diagnosis, s.name AS surgery, COUNT(*) AS num_procedures, SUM(CASE WHEN a.stay_length_of_day <= 4 THEN 1 ELSE 0 END) AS procedures_in_first_four_days, SUM(CASE WHEN a.stay_length_of_day > 4 THEN 1 ELSE 0 END) AS procedures_after_four_days FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN diagnoses_icd d ON a.subject_id = d.subject_id JOIN procedures_icd s ON a.subject_id = s.subject_id WHERE p.gender = 'F' AND CAST(p.anchor_age AS INT) BETWEEN 80 AND 90 AND d.icd_code = '64572' GROUP BY p.gender, age, diagnosis, surgery ORDER BY p.gender, age, diagnosis, surgery NULLS LAST;